class Solution {
public:
    TreeNode* constructMaximumBinaryTree(vector<int>& nums) {
        vector<TreeNode*> stk;
        for (int x : nums) {
            TreeNode* node = new TreeNode(x);
            TreeNode* last = nullptr;
            while (!stk.empty() && stk.back()->val < x) {
                last = stk.back();
                stk.pop_back();
            }
            node->left = last;
            if (!stk.empty()) {
                stk.back()->right = node;
            }
            stk.push_back(node);
        }
        return stk.front();
    }
};
